e }}</option>@endforeach</select></div><div><label>Quantity to produce *</label><input id="quantity" name="quantity" type="number" min="0.0001" step="0.0001" required><small id="quantity-help" class="text-slate-500"></small></div><div><label>Manufacturing date *</label><input id="manufactured_at" name="manufactured_at" type="date" max="{{ now()->toDateString() }}" value="{{ now()->toDateString() }}" required></div><div><label>Expiry date</label><input id="expires_at" name="expires_at" type="date"></div><div class="wide"><label>Notes</label><textarea name="notes" rows="2" maxlength="2000"></textarea></div></div><div class="mt-5 text-right"><button type="button" class="serial-btn next-step" data-next="2">Continue to materials <i class="bi bi-arrow-right"></i></button></div></section>
