@push('scripts')<script>
AppPage.ready(()=>{const boms=@json($bomData),steps=[...document.querySelectorAll('.mfg-step')],panels=[...document.querySelectorAll('.wizard-panel')],product=document.getElementById('product_id'),bomSelect=document.getElementById('bill_of_material_id'),qty=document.getElementById('quantity'),expenses=document.getElementById('expense-lines');let expenseIndex=0;
const productSearch=document.getElementById('product-search'),productResults=document.getElementById('product-results'),productOptions=[...product.options].filter(o=>o.value);let productActive=-1;
function renderProductResults(){const term=productSearch.value.trim().toLowerCase(),matches=productOptions.filter(o=>!term||(o.textContent+' '+(o.dataset.name||'')).toLowerCase().includes(term));productResults.innerHTML='';productActive=-1;if(!matches.length){productResults.innerHTML='<div class="mfg-product-empty">No matching manufacturable product found.</div>'}else matches.forEach(o=>{const b=document.createElement('button');b.type='button';b.className='mfg-product-option';b.textContent=o.textContent.trim();b.onclick=()=>selectProduct(o);productResults.append(b)});productResults.hidden=false;productSearch.setAttribute('aria-expanded','true')}
function selectProduct(option){product.value=option.value;productSearch.value=option.textContent.trim();productResults.hidden=true;productSearch.setAttribute('aria-expanded','false');product.dispatchEvent(new Event('change'))}
function moveProduct(delta){const buttons=[...productResults.querySelectorAll('.mfg-product-option')];if(!buttons.length)return;productActive=(productActive+delta+buttons.length)%buttons.length;buttons.forEach((b,i)=>b.classList.toggle('active',i===productActive));buttons[productActive].scrollIntoView({block:'nearest'})}
productSearch.addEventListener('focus',renderProductResults);productSearch.addEventListener('input',()=>{product.value='';recipes();renderProductResults()});productSearch.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();moveProduct(1)}else if(e.key==='ArrowUp'){e.preventDefault();moveProduct(-1)}else if(e.key==='Enter'&&productActive>=0){e.preventDefault();productResults.querySelectorAll('.mfg-product-option')[productActive].click()}else if(e.key==='Escape'){productResults.hidden=true;productSearch.setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(!e.target.closest('.mfg-product-search')){productResults.hidden=true;productSearch.setAttribute('aria-expanded','false')}});
const selectedBom=()=>boms.find(b=>b.id==bomSelect.value),money=n=>'Rs '+Number(n||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
function scaled(){const b=selectedBom(),scale=b&&+qty.value?+qty.value/b.output_quantity:0;return b?b.items.map(i=>({...i,required:i.quantity*scale,total:i.quantity*scale*i.unit_cost})):[]}
function renderMaterials(){const b=selectedBom(),rows=scaled();document.getElementById('recipe-lines').innerHTML=!b?'<p class="rounded-xl bg-amber-50 p-4 text-amber-800">Select a recipe in Step 1.</p>':`<div class="mb-3 rounded-xl bg-purple-50 p-3 text-sm"><b>${b.code}</b> produces ${b.output_quantity} base unit(s). Required quantities below are for ${+qty.value||0} unit(s).</div><table class="serial-table"><thead><tr><th>Raw material</th><th>Recipe qty</th><th>Required qty</th><th>Estimated cost</th></tr></thead><tbody>${rows.map(i=>`<tr><td><b>${i.name}${i.variant?' Â· '+i.variant:''}</b><small class="block">${i.sku}</small></td><td>${i.quantity} ${i.unit}</td><td class="font-bold text-purple-700">${i.required} ${i.unit}</td><td>${money(i.total)}</td></tr>`).join('')}</tbody></table>`}
function go(n){if(n>1&&(!product.value||!bomSelect.value||!document.getElementById('location_id').value||!(+qty.value>0))){alert('Select the product, recipe, warehouse and output quantity first.');return}steps.forEach(s=>{s.classList.toggle('active',+s.dataset.step===n);s.classList.toggle('done',+s.dataset.step<n)});panels.forEach(p=>p.classList.toggle('active',+p.dataset.panel===n));if(n===2)renderMaterials();if(n===3)review()}
function recipes(){const list=boms.filter(b=>b.product_id==product.value);bomSelect.disabled=!list.length;bomSelect.innerHTML=list.length?'<option value="">Select recipe</option>'+list.map(b=>`<option value="${b.id}">${b.code} Â· base output ${b.output_quantity}</option>`).join(''):'<option value="">No active recipe â€” create one first</option>';document.getElementById('bom-help').innerHTML=list.length?`${list.length} active recipe(s) available.`:`This product needs an active recipe. <a class="font-bold text-purple-700 underline" href="{{ route('manufacturing.boms.create') }}">Create recipe</a>`;const o=product.selectedOptions[0],serial=o?.dataset.serial==='1';document.getElementById('selling_price').value=o?.dataset.selling||0;qty.step=serial?'1':'0.0001';document.getElementById('quantity-help').textContent=serial?'One unique serial number will be required for every finished unit.':'';expiry()}
function addExpense(){const n=document.getElementById('expense-template').content.firstElementChild.cloneNode(true),i=expenseIndex++;n.querySelector('.expense-name').name=`expenses[${i}][name]`;n.querySelector('.expense-amount').name=`expenses[${i}][amount]`;n.querySelector('.remove-row').onclick=()=>n.remove();expenses.append(n)}
function review(){const rows=scaled(),material=rows.reduce((s,i)=>s+i.total,0),expense=[...expenses.querySelectorAll('.expense-amount')].reduce((s,e)=>s+(+e.value||0),0),total=material+expense,o=product.selectedOptions[0],b=selectedBom();document.getElementById('review').innerHTML=`<div class="grid gap-3 rounded-xl bg-purple-50 p-4 md:grid-cols-3"><div><small>Finished product</small><b class="block">${o?.dataset.name||''}</b></div><div><small>Recipe</small><b class="block">${b?.code||''}</b></div><div><small>Output</small><b class="block">${+qty.value} ${o?.dataset.unit||''}</b></div></div><table class="serial-table mt-4"><thead><tr><th>Material</th><th>Required</th><th>Cost</th></tr></thead><tbody>${rows.map(i=>`<tr><td>${i.name}</td><td>${i.required} ${i.unit}</td><td>${money(i.total)}</td></tr>`).join('')}</tbody></table><div class="mt-4 rounded-xl bg-slate-900 p-4 text-white"><div class="flex justify-between"><span>Materials</span><b>${money(material)}</b></div><div class="flex justify-between"><span>Expenses</span><b>${money(expense)}</b></div><div class="mt-2 flex justify-between border-t border-white/20 pt-2"><span>Total / estimated unit cost</span><b>${money(total)} / ${money(total/(+qty.value||1))}</b></div></div>`}
function expiry(){const o=product.selectedOptions[0],date=document.getElementById('manufactured_at').value;if(!date||!o?.dataset.expiry)return;const d=new Date(date+'T00:00:00');o.dataset.expiryType==='months'?d.setMonth(d.getMonth()+(+o.dataset.expiry)):d.setDate(d.getDate()+(+o.dataset.expiry));document.getElementById('expires_at').value=d.toISOString().slice(0,10)}
steps.forEach(s=>s.querySelector('button').onclick=()=>go(+s.dataset.step));document.querySelectorAll('.next-step').forEach(b=>b.onclick=()=>go(+b.dataset.next));product.onchange=recipes;bomSelect.onchange=renderMaterials;qty.oninput=renderMaterials;document.getElementById('manufactured_at').onchange=expiry;document.getElementById('add-expense').onclick=addExpense;document.getElementById('mfg-form').onsubmit=()=>document.getElementById('process-button').disabled=true;addExpense()});
</script>@endpush
